fn payload(ur: &str) -> alloc::vec::Vec<u8> {
    let decoded = ur_decode::decode(ur).expect("ur decodes");
    assert_eq!(decoded.type_tag(), UrTypeTag::EthSignRequest);
    decoded.as_ref().to_vec()
}

/// Sign through the workspace-provisioned entry — the face every C-ABI sign call uses, so
/// a typed-data request has the container region it needs. `sign()` (no workspace) refuses
/// typed data with `BufferTooSmall` by design; that is not what this matrix is about.
fn device_sign(payload: &[u8], out: &mut [u8]) -> Result<usize, shlosilo::error::ShlosiloError> {
    use shlosilo::error::ShlosiloError;
    let need = SignWsLayout::compute().total;
    let mut ws_bytes = alloc::vec![0u8; need];
    let mut ws = carve_sign_ws(&mut ws_bytes).expect("workspace carve");
    let seed = [7u8; 64];
    sign_with_entropy_ws(
        SignInput::Seed { seed: &seed },
        UrTypeTag::EthSignRequest,
        payload,
        &[],
        &[],
        Some(&mut ws),
        None,
        out,
    )
    .map_err(|e: ShlosiloError| e)
}

fn review_text(view: &review::ReviewView) -> alloc::string::String {
    let mut s = alloc::string::String::new();
    for l in view.lines() {
        s.push_str(l.as_str());
        s.push('\n');
    }
    s
}

#[test]
fn the_matrix_matches_the_device_behaviour() {
    for case in CASES {
        let payload = payload(case.ur);
        match case.expect {
            Expect::Sign {
                review_has,
                v_domain,
            } => {
                let mut td_ws = alloc::vec![0u8; shlosilo::ffi::c_abi::review_ws_len()];
                let view = review::build_eth(&payload, &mut td_ws).unwrap_or_else(|e| {
                    panic!(
                        "{}: review must render, got {:?} {:?}",
                        case.kind, e.kind, e.context
                    )
                });
                let text = review_text(&view);
                for needle in review_has {
                    assert!(
                        text.contains(needle),
                        "{}: review must contain {needle:?}; got:\n{text}",
                        case.kind
                    );
                }

                let mut out = [0u8; 512];
                let n = device_sign(&payload, &mut out)
                    .unwrap_or_else(|e| panic!("{}: must sign, got {:?}", case.kind, e.kind));
                let sig = parse_eth_signature(&out[..n])
                    .unwrap_or_else(|_| panic!("{}: exit must be a container", case.kind));
                match v_domain {
                    VDomain::YParity => {
                        let v = sig.signature[64];
                        assert!(
                            v <= 1,
                            "{}: EIP-1559 carries the bare yParity, got v={v}",
                            case.kind
                        )
                    }
                    VDomain::Eip191 => {
                        let v = sig.signature[64];
                        assert!(
                            v == 27 || v == 28,
                            "{}: EIP-191 carries v = 27/28, got v={v}",
                            case.kind
                        )
                    }
                    VDomain::Eip712 => {
                        // EIP-712 shares personal_sign's convention: a 27/28 byte, not
                        // EIP-1559's bare parity. The container's v slot must be exactly
                        // one byte here (`signature_len` = 65).
                        assert_eq!(
                            sig.signature_bytes().len(),
                            65,
                            "{}: a typed-data v is one byte",
                            case.kind
                        );
                        let v = sig.signature[64];
                        assert!(
                            v == 27 || v == 28,
                            "{}: EIP-712 carries v = 27/28, got v={v}",
                            case.kind
                        )
                    }
                    VDomain::Eip155 { chain_id } => {
                        // Whatever the parity, the wire `v` must decode back to this
                        // chain id: chain_id = (v - 35) / 2, and the bytes must be the
                        // minimal big-endian form of that v (no padding).
                        let v_bytes = &sig.signature_bytes()[64..];
                        assert!(
                            (1..=8).contains(&v_bytes.len()),
                            "{}: v is 1..=8 bytes, got {}",
                            case.kind,
                            v_bytes.len()
                        );
                        assert!(
                            v_bytes[0] != 0x00,
                            "{}: v must not carry a leading zero byte",
                            case.kind
                        );
                        let mut v: u64 = 0;
                        for b in v_bytes {
                            v = (v << 8) | u64::from(*b);
                        }
                        assert!(
                            v >= 35 && (v - 35) / 2 == chain_id,
                            "{}: v={v} must decode to chain {chain_id}",
                            case.kind
                        );
                    }
                }
            }
            Expect::Refuse(kind) => {
                let mut td_ws2 = alloc::vec![0u8; shlosilo::ffi::c_abi::review_ws_len()];
                match review::build_eth(&payload, &mut td_ws2) {
                    Ok(view) => panic!(
                        "{}: review must refuse, but rendered:\n{}",
                        case.kind,
                        review_text(&view)
                    ),
                    Err(e) => assert_eq!(e.kind, kind, "{}: review code", case.kind),
                }
                let mut out = [0u8; 512];
                match device_sign(&payload, &mut out) {
                    Ok(_) => panic!("{}: must not sign", case.kind),
                    Err(e) => assert_eq!(e.kind, kind, "{}: sign code", case.kind),
                }
            }
        }
    }
}

/// An `approve` signature is only useful if it verifies. This recovers the signer of
/// both approve payloads (finite and unlimited) with the plain EIP-1559 digest and
/// compares it with the public key derived from the same seed/path the exit used — so
/// "the device approved a spender" is checked with the same arithmetic a node would
/// apply, without broadcasting anything.
#[test]
fn approve_signatures_recover_to_the_device_address() {
    use shlosilo::address::eth as eth_address;
    use shlosilo::chain::eth::{eip1559, from_rlp, sign as eth_sign};
    use shlosilo::curve_primitive::secp256k1;
    use shlosilo::derivation::bip32_secp256k1::derive_from_seed;
    use shlosilo::derivation::path::DerivationPath;
    use shlosilo::encoding::keccak256;
    use shlosilo::ur::codec::eth_sign_request::parse_eth_sign_request;

    let seed = [7u8; 64];
    let path = DerivationPath::parse("m/44'/60'/0'/0/0").unwrap();
    let sk = derive_from_seed(&seed, &path).unwrap();
    let device_pub = secp256k1::point_to_uncompressed(&secp256k1::base_mul(&sk));

    for kind in ["approve", "approve-unlimited"] {
        let case = CASES
            .iter()
            .find(|c| c.kind == kind)
            .expect("approve case present");
        let payload = payload(case.ur);
        let req = parse_eth_sign_request(&payload).expect("request parses");
        let tx = from_rlp::parse_eip1559_signing_request(req.sign_data).expect("tx parses");
        let sighash = eip1559::signing_hash(&tx).expect("sighash");

        let mut out = [0u8; 512];
        let n = sign(
            SignInput::Seed { seed: &seed },
            UrTypeTag::EthSignRequest,
            &payload,
            &mut out,
        )
        .expect("signs");
        let sig = parse_eth_signature(&out[..n]).expect("container");

        // The container carries the bare yParity; recovery takes the EIP-191-style
        // 27/28 form, so the offset is applied here (never on the wire). The
        // container's signature slot is 72 bytes wide (EIP-155's `v` is a u64), so
        // the 65-byte recovery form is built explicitly.
        let mut sig65 = [0u8; 65];
        sig65.copy_from_slice(&sig.signature_bytes()[..65]);
        sig65[64] += 27;
        let recovered = eth_sign::ecdsa_recover(&sighash, &sig65).expect("recover");
        assert_eq!(
            recovered,
            device_pub[1..],
            "{kind}: the signature must verify against the device's own public key"
        );

        let h = keccak256::hash(&recovered).unwrap();
        let mut addr = [0u8; 20];
        addr.copy_from_slice(&h[12..]);
        let rendered = eth_address::encode_bytes(&addr).unwrap();
        assert_eq!(
            rendered.as_ref().len(),
            42,
            "{kind}: address renders as an EIP-55 string"
        );
    }
}

/// E-1 (2026-11-25): a legacy (EIP-155) signature is only usable if `v` is the
/// protected form the network expects. This closes the loop the same way
/// `approve_signatures_recover_to_the_device_address` does for 1559: recompute the
/// EIP-155 preimage digest with our own code, take `r ‖ s ‖ v` **straight off the
/// wire**, undo the `chain_id*2 + 35` offset exactly as a wallet does
/// (`parity = (v - 35) % 2`), and recover the signer. The recovered key must be the
/// device's own — so a `v` from the wrong chain, a truncated `v`, or a 27/28
/// substitution all fail here instead of at a user's wallet.
#[test]
fn legacy_signature_recovers_to_the_device_address() {
    use shlosilo::chain::eth::{eip155, from_rlp, sign as eth_sign};
    use shlosilo::curve_primitive::secp256k1;
    use shlosilo::derivation::bip32_secp256k1::derive_from_seed;
    use shlosilo::derivation::path::DerivationPath;
    use shlosilo::encoding::keccak256;
    use shlosilo::ur::codec::eth_sign_request::parse_eth_sign_request;

    let seed = [7u8; 64];
    let path = DerivationPath::parse("m/44'/60'/0'/0/0").unwrap();
    let sk = derive_from_seed(&seed, &path).unwrap();
    let device_pub = secp256k1::point_to_uncompressed(&secp256k1::base_mul(&sk));

    let case = CASES
        .iter()
        .find(|c| c.kind == "legacy")
        .expect("legacy case present");
    let payload = payload(case.ur);
    let req = parse_eth_sign_request(&payload).expect("request parses");
    let tx = from_rlp::parse_eip155_signing_request(req.sign_data).expect("legacy tx parses");
    assert_eq!(tx.chain_id, 1, "the fixture is a mainnet transaction");
    // the digest the network would compute for this preimage
    let sighash = eip155::signing_hash(&tx).expect("sighash");

    let mut out = [0u8; 512];
    let n = sign(
        SignInput::Seed { seed: &seed },
        UrTypeTag::EthSignRequest,
        &payload,
        &mut out,
    )
    .expect("legacy signs");
    let sig = parse_eth_signature(&out[..n]).expect("container");

    // v off the wire, minimal big-endian
    let v_bytes = &sig.signature_bytes()[64..];
    let mut v: u64 = 0;
    for b in v_bytes {
        v = (v << 8) | u64::from(*b);
    }
    assert_eq!(
        v, 37,
        "chain 1 → v = 37 or 38, and this fixture's parity is 0"
    );

    // what a wallet does with an EIP-155 v: strip the chain, keep the parity
    let parity = ((v - 35) % 2) as u8;
    let mut sig65 = [0u8; 65];
    sig65[..64].copy_from_slice(&sig.signature_bytes()[..64]);
    sig65[64] = 27 + parity;

    let recovered = eth_sign::ecdsa_recover(&sighash, &sig65).expect("recover");
    assert_eq!(
        recovered,
        device_pub[1..],
        "a legacy signature must recover to the device's own key from the wire bytes"
    );

    // ... and the same signature with the 27-offset v (what a 1559/personal-shaped
    // container would have carried) recovers to something else: the offset is not
    // cosmetic.
    let mut wrong = sig65;
    wrong[64] = 27 + (1 - parity);
    let mis_recovered = eth_sign::ecdsa_recover(&sighash, &wrong).expect("recover (wrong parity)");
    assert_ne!(
        mis_recovered,
        device_pub[1..],
        "flipping the parity must not recover to the device key"
    );

    // keccak256(preimage) is the digest our model re-derives: pin it against the
    // preimage bytes so a re-encoding drift cannot hide behind a matching signature
    let mut preimage = [0u8; 256];
    let pn = eip155::signing_preimage_into(&tx, &mut preimage).expect("preimage");
    assert_eq!(
        keccak256::hash(&preimage[..pn]).unwrap(),
        sighash,
        "the digest must be keccak256 of the EIP-155 preimage"
    );
}
